-- =====================================================================
--  nasa_license : 통합 PostgreSQL 스키마 (onlic Linux 포팅)
--  원본: 190.44 Nasa_License (라이선스: lic_access_list, IPCS_LOG, nasa_lic*, nasa_security, CALLBOX_LOG, SOFTPHONE_LOG)
--        190.7  NASA_License (알람: CallCenter_Link, SITE_*, OnAlarm 웹 테이블)
--  생성: gen_pg_schema.py (2026-10-13), 근거: server/db/01_*, 08_*, 44_05_* (INFORMATION_SCHEMA 읽기 조회)
--  규칙:
--    - 식별자는 모두 소문자 (PostgreSQL 은 따옴표 없는 식별자를 소문자로 접으므로 코드의 CallCenter_Link, IPCS_LOG 등은 그대로 동작)
--    - identity → GENERATED BY DEFAULT AS IDENTITY (이관 시 원본 값 유지 가능, 이후 setval 로 보정: 03_post_migrate.sql)
--    - smalldatetime → timestamp(0), datetime → timestamp, getdate()/sysdatetime() → now()
--    - PK/FK/인덱스는 원본 그대로 + onlic 권고 인덱스(끝부분)
--    - 재실행 가능: CREATE TABLE/INDEX IF NOT EXISTS, FK 는 존재 검사 후 추가 (기존 테이블·데이터는 건드리지 않음)
--  적용:  createdb -E UTF8 --locale=C nasa_license   (서버 인코딩 UTF8, 클라이언트는 EUCKR 로 접속: onlic set client_encoding)
--         psql -d nasa_license -f 01_nasa_license_schema.sql
-- =====================================================================

-- CALLBOX_LOG  (원본 190.44, 두 서버 공통)
CREATE TABLE IF NOT EXISTS callbox_log (
    log_index              bigint GENERATED BY DEFAULT AS IDENTITY,
    log_data               varchar(100) NOT NULL,
    log_ip                 varchar(20),
    log_type               varchar(50) NOT NULL,
    log_real_ip            varchar(20),
    log_insert_date        timestamp(0) DEFAULT now(),
    log_update_day         varchar(50) NOT NULL,
    log_result             char(10) DEFAULT 'Y',
    CONSTRAINT pk_callbox_log PRIMARY KEY (log_data, log_index, log_type)
);

-- CallCenter_Link  (원본 190.7)
CREATE TABLE IF NOT EXISTS callcenter_link (
    cc_index               bigint GENERATED BY DEFAULT AS IDENTITY,
    cc_name                varchar(256) DEFAULT '',
    cc_site_name           varchar(256) DEFAULT '',
    cc_ip                  varchar(50) NOT NULL DEFAULT '',
    cc_real_ip             varchar(50) NOT NULL DEFAULT '',
    cc_use                 char(1) DEFAULT 'Y',
    cc_insert_time         timestamp DEFAULT now(),
    cc_update_time         varchar(256) DEFAULT '',
    cc_link_error          varchar(1) DEFAULT 'N',
    cc_pause               varchar(50) DEFAULT '',
    cc_domain              varchar(50),
    cc_memo                text,
    db_user                varchar(256),
    db_pwd                 varchar(256),
    db_port                varchar(100),
    db_name                varchar(256),
    db_type                varchar(100),
    db_ip                  varchar(100),
    cc_nas_failcnt         integer DEFAULT 0,
    cc_nasupload_fail      varchar(128) DEFAULT '',
    CONSTRAINT pk_callcenter_link PRIMARY KEY (cc_index)
);

-- CallCenter_Link_Reference  (원본 190.7)
CREATE TABLE IF NOT EXISTS callcenter_link_reference (
    ccr_index              bigint GENERATED BY DEFAULT AS IDENTITY,
    cc_index               bigint NOT NULL,
    ccr_user_department    varchar(10) NOT NULL,
    comment                text,
    use_yn                 varchar(1) NOT NULL DEFAULT 'Y',
    create_by              varchar(50) NOT NULL,
    create_date            timestamp NOT NULL DEFAULT now(),
    modify_by              varchar(50),
    modify_date            timestamp,
    CONSTRAINT pk_callcenter_link_reference PRIMARY KEY (ccr_index)
);

-- enterprise  (원본 190.7)
CREATE TABLE IF NOT EXISTS enterprise (
    idx                    bigint GENERATED BY DEFAULT AS IDENTITY,
    call_center_link_idx   bigint,
    enterprise_type        varchar(256),
    industry_type          varchar(256),
    contractor             varchar(50),
    product                varchar(256),
    contract_type          varchar(50),
    transaction_status     varchar(50),
    technical_support_yn   varchar(1),
    primary_contact        varchar(50),
    secondary_contact      varchar(50),
    ipcc                   integer,
    ipt                    integer,
    vrs                    integer,
    jira_project_id        varchar(256),
    service_start_date     date,
    comment                text,
    use_yn                 varchar(1) DEFAULT 'Y',
    create_by              varchar(50),
    create_date            timestamp,
    modify_by              varchar(50),
    modify_date            timestamp,
    CONSTRAINT pk_enterprise PRIMARY KEY (idx)
);

-- IPCS_LOG  (원본 190.44, 두 서버 공통)
CREATE TABLE IF NOT EXISTS ipcs_log (
    lic_index              bigint GENERATED BY DEFAULT AS IDENTITY,
    lic_insert_date        timestamp(0) NOT NULL DEFAULT now(),
    log_data               varchar(200),
    log_ip                 varchar(50),
    log_type               varchar(10),
    log_real_ip            varchar(50),
    CONSTRAINT pk_ipcs_log PRIMARY KEY (lic_index, lic_insert_date)
);

-- lic_access_list  (원본 190.44)
CREATE TABLE IF NOT EXISTS lic_access_list (
    lic_ip_index           integer GENERATED BY DEFAULT AS IDENTITY,
    nasa_con_ip            varchar(50) NOT NULL,
    nasa_insert_date       varchar(20),
    nasa_use               varchar(10) DEFAULT 'Y',
    CONSTRAINT pk_lic_access_list PRIMARY KEY (lic_ip_index, nasa_con_ip)
);

-- nasa_lic  (원본 190.44, 두 서버 공통)
CREATE TABLE IF NOT EXISTS nasa_lic (
    nl_index               integer GENERATED BY DEFAULT AS IDENTITY,
    nl_site_name           varchar(100),
    nl_official            varchar(50),
    nl_mac_addr            varchar(50),
    nl_expires_day         varchar(10),
    nl_line                integer,
    nl_lic_type            varchar(10),
    nl_key                 varchar(50),
    nl_ins_gip             varchar(50),
    nl_ins_lip             varchar(50),
    nl_ins_date            timestamp(0) DEFAULT now(),
    nl_update_date         varchar(20),
    nl_del_date            varchar(20),
    nl_use                 char(1) DEFAULT 'Y',
    nl_mod_gip             varchar(50),
    nl_mod_lip             varchar(50),
    nl_del_gip             varchar(50),
    nl_del_lip             varchar(50),
    nl_description         varchar(500),
    nl_bit                 varchar(50),
    CONSTRAINT pk_nasa_lic PRIMARY KEY (nl_index)
);

-- nasa_lic_log  (원본 190.44, 두 서버 공통)
CREATE TABLE IF NOT EXISTS nasa_lic_log (
    nlog_index             bigint GENERATED BY DEFAULT AS IDENTITY,
    nlog_official          varchar(50),
    nlog_gip               varchar(50),
    nlog_lip               varchar(50),
    nlog_type              varchar(50),
    nlog_text              varchar(500),
    nlog_date              timestamp(0) DEFAULT now(),
    CONSTRAINT pk_nasa_lic_log PRIMARY KEY (nlog_index)
);

-- nasa_security  (원본 190.44, 두 서버 공통)
CREATE TABLE IF NOT EXISTS nasa_security (
    ns_official            varchar(50) NOT NULL,
    ns_password            varchar(30) NOT NULL,
    ns_ins_date            timestamp(0) DEFAULT now(),
    ns_use                 char(1),
    CONSTRAINT pk_nasa_security PRIMARY KEY (ns_official, ns_password)
);

-- on_alarm_user  (원본 190.7)
CREATE TABLE IF NOT EXISTS on_alarm_user (
    oau_idx                bigint GENERATED BY DEFAULT AS IDENTITY,
    oau_id                 varchar(20),
    oau_pw                 varchar(256),
    oau_name               varchar(30),
    oau_auth               varchar(10),
    oau_department         varchar(20),
    comment                text,
    use_yn                 varchar(1) NOT NULL DEFAULT 'Y',
    create_by              varchar(50) NOT NULL,
    create_date            timestamp NOT NULL DEFAULT now(),
    modify_by              varchar(50),
    modify_date            timestamp,
    CONSTRAINT pk_on_alarm_user PRIMARY KEY (oau_idx)
);

-- project  (원본 190.7)
CREATE TABLE IF NOT EXISTS project (
    idx                    bigint GENERATED BY DEFAULT AS IDENTITY,
    call_center_link_idx   bigint,
    name_kr                varchar(256),
    name_eng               varchar(256),
    manager                varchar(50),
    login_id               varchar(50),
    login_password         varchar(256),
    ssl_issuance_date      date,
    ssl_expiration_date    date,
    repository             varchar(500),
    deploy_port            integer,
    deploy_jdk_version     integer,
    deploy_service_name    varchar(50),
    deploy_path            varchar(256),
    deploy_backup_path     varchar(256),
    custom                 varchar(500),
    comment                text,
    use_yn                 varchar(1) DEFAULT 'Y',
    create_by              varchar(50),
    create_date            timestamp,
    modify_by              varchar(50),
    modify_date            timestamp,
    CONSTRAINT pk_project PRIMARY KEY (idx)
);

-- server  (원본 190.7)
CREATE TABLE IF NOT EXISTS server (
    idx                    bigint GENERATED BY DEFAULT AS IDENTITY,
    call_center_link_idx   bigint NOT NULL,
    name_kr                varchar(256),
    name_eng               varchar(256),
    domain                 varchar(256),
    ip                     varchar(50),
    real_ip                varchar(50),
    ssh_port               integer DEFAULT 7300,
    ssh_id                 varchar(50) DEFAULT 'root',
    ssh_password           varchar(256),
    db_type                varchar(50),
    db_port                integer,
    db_id                  varchar(50),
    db_password            varchar(256),
    redundancy_yn          varchar(1),
    infrastructure_type    varchar(50),
    location               varchar(50),
    network_type           varchar(50),
    os                     varchar(256),
    cpu                    varchar(256),
    ram                    varchar(50),
    comment                text,
    use_yn                 varchar(1) DEFAULT 'Y',
    create_by              varchar(50),
    create_date            timestamp,
    modify_by              varchar(50),
    modify_date            timestamp,
    CONSTRAINT pk_server PRIMARY KEY (idx)
);

-- SITE_AUTH  (원본 190.7)
CREATE TABLE IF NOT EXISTS site_auth (
    ca_ip                  varchar(50) NOT NULL,
    ca_id                  varchar(50),
    ca_cti_id              varchar(50),
    ca_cti_pw              varchar(50),
    ca_ssw_id              varchar(50),
    ca_ssw_pw              varchar(50),
    ca_memo                text
);

-- SITE_EMAIL_USER  (원본 190.7)
CREATE TABLE IF NOT EXISTS site_email_user (
    idx                    bigint GENERATED BY DEFAULT AS IDENTITY,
    email_site_ip          varchar(50) NOT NULL DEFAULT '',
    email_site_real_ip     varchar(50) NOT NULL DEFAULT '',
    email_site_name        varchar(100) DEFAULT '',
    alarm_type             integer DEFAULT 0,
    alarm_proc_name        varchar(50) DEFAULT '',
    email_to               varchar(500) DEFAULT '',
    email_from             varchar(200) DEFAULT 'support@onpia.co.kr',
    email_title            varchar(200) DEFAULT '',
    email_msg1             varchar(500) DEFAULT '',
    email_msg2             varchar(500) DEFAULT '',
    email_msg3             varchar(500) DEFAULT '',
    email_url              varchar(2048) DEFAULT 'http://203.239.190.7/',
    email_attr1            varchar(100) DEFAULT '',
    email_attr2            varchar(100) DEFAULT '',
    email_attr3            varchar(100) DEFAULT ''
);

-- SITE_SMS_BASIC_USER  (원본 190.7)
CREATE TABLE IF NOT EXISTS site_sms_basic_user (
    site_sms_index         bigint GENERATED BY DEFAULT AS IDENTITY,
    site_sms_name          varchar(50) NOT NULL,
    site_sms_telnum        varchar(50) NOT NULL,
    site_sms_use           char(1) NOT NULL
);

-- SITE_SMS_USER  (원본 190.7)
CREATE TABLE IF NOT EXISTS site_sms_user (
    sms_site_ip            varchar(50) NOT NULL,
    sms_site_real_ip       varchar(50) NOT NULL,
    sms_site_name          varchar(256),
    sms_use                char(1) NOT NULL,
    sms_user_name          varchar(50),
    sms_user_phone         varchar(50) NOT NULL
);

-- SITE_SmsExcludeTime  (원본 190.7)
CREATE TABLE IF NOT EXISTS site_smsexcludetime (
    sm_index               integer GENERATED BY DEFAULT AS IDENTITY,
    sm_type                integer,
    sm_msg                 varchar(200),
    sm_stime               varchar(10),
    sm_etime               varchar(10),
    sm_use                 char(2) DEFAULT 'Y'
);

-- SOFTPHONE_LOG  (원본 190.44, 두 서버 공통)
CREATE TABLE IF NOT EXISTS softphone_log (
    log_index              bigint GENERATED BY DEFAULT AS IDENTITY,
    log_data               varchar(100) NOT NULL,
    log_ip                 varchar(20),
    log_type               varchar(50) NOT NULL,
    log_real_ip            varchar(20),
    log_insert_date        timestamp(0) DEFAULT now(),
    log_update_day         varchar(50) NOT NULL,
    log_result             char(10) DEFAULT 'Y',
    CONSTRAINT pk_softphone_log PRIMARY KEY (log_data, log_index, log_type)
);

-- stc_calllist  (원본 190.7)
CREATE TABLE IF NOT EXISTS stc_calllist (
    idx                    integer GENERATED BY DEFAULT AS IDENTITY,
    stc_date               timestamp,
    stc_number             varchar(50)
);

DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'callcenter_link_reference_callcenter_link_cc_index_fk') THEN
    ALTER TABLE callcenter_link_reference ADD CONSTRAINT callcenter_link_reference_callcenter_link_cc_index_fk FOREIGN KEY (cc_index) REFERENCES callcenter_link(cc_index);
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS ix_callcenter_link_cc_use ON callcenter_link (cc_use);
CREATE INDEX IF NOT EXISTS ix_callcenter_link_reference_cc_index_use_yn_ccr_index ON callcenter_link_reference (cc_index, use_yn, ccr_index);
CREATE INDEX IF NOT EXISTS ix_site_auth_ca_ip_ca_id ON site_auth (ca_ip, ca_id);

-- onlic 권고 인덱스 (docs/DB스키마.md §6) : 원본에는 없음. 조회 경로 기준
CREATE INDEX IF NOT EXISTS ix_callcenter_link_ip ON callcenter_link (cc_ip, cc_real_ip);
CREATE INDEX IF NOT EXISTS ix_callcenter_link_update ON callcenter_link (cc_use, cc_link_error, cc_update_time);
CREATE INDEX IF NOT EXISTS ix_site_sms_user_site ON site_sms_user (sms_use, sms_site_ip, sms_site_real_ip);
CREATE INDEX IF NOT EXISTS ix_site_email_user_site ON site_email_user (email_site_ip, email_site_real_ip, alarm_type);
CREATE INDEX IF NOT EXISTS ix_lic_access_list_ip ON lic_access_list (nasa_con_ip, nasa_use);
CREATE INDEX IF NOT EXISTS ix_ipcs_log_date ON ipcs_log (lic_insert_date);

-- 알림톡 큐는 외부 PostgreSQL(onpia_check, 203.239.159.134:39999) 그대로 사용 - 이 DB 에 만들지 않음
-- SDK_SMS_SEND(tcssdk) 는 SMS Agent 설치 시 별도 (확인결정사항 B5)
